<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Holder\UserInvitationAcceptedAtAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationAcceptedAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserInvitationAcceptedAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAcceptedAt returns null on a freshly created holder.
     */
    public function testAcceptedAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationAcceptedAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAcceptedAtAssigned());
        $this->assertNull($holder->getAcceptedAt());
    }
}
class ImplWithUserInvitationAcceptedAtAttributeHolderUnitTest
{
    use UserInvitationAcceptedAtAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedAcceptedAtRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultAcceptedAt();
    }
}
